namespace sv_940b4722b8e342f4a1af21b574f14d25.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_940b4722b8e342f4a1af21b574f14d25.Components.Pages.ApplyForm

<nav aria-label="Application progress" class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between position-relative px-0">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var isCurrent = stepIndex == CurrentStep;
            var isCompleted = CompletedSteps.Contains(stepIndex);
            var isFuture = !isCurrent && !isCompleted;

            <li class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")">
                @if (isCompleted)
                {
                    <button class="btn btn-link p-0 text-decoration-none" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-circle bg-success text-white">&#10003;</span>
                        <span class="step-label d-block mt-1 small text-success fw-semibold">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <div>
                        <span class="step-circle @(isCurrent ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">@(stepIndex + 1)</span>
                        <span class="step-label d-block mt-1 small @(isCurrent ? "text-primary fw-semibold" : "text-muted")">@StepNames[stepIndex]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };
}

@namespace sv_940b4722b8e342f4a1af21b574f14d25.Components.Pages.ApplyForm

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-3">Personal Information</h4>

        <div class="mb-3">
            <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
            <input id="fullName" class="form-control @ValidationClass(nameof(FullName))" @bind="FullName" />
            @if (Errors.ContainsKey(nameof(FullName)))
            {
                <div class="invalid-feedback d-block">@Errors[nameof(FullName)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
            <input id="email" type="email" class="form-control @ValidationClass(nameof(Email))" @bind="Email" />
            @if (Errors.ContainsKey(nameof(Email)))
            {
                <div class="invalid-feedback d-block">@Errors[nameof(Email)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone" class="form-label">Phone <span class="text-danger">*</span></label>
            <input id="phone" type="tel" class="form-control @ValidationClass(nameof(Phone))" @bind="Phone" />
            @if (Errors.ContainsKey(nameof(Phone)))
            {
                <div class="invalid-feedback d-block">@Errors[nameof(Phone)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="address" class="form-label">Address <span class="text-danger">*</span></label>
            <textarea id="address" class="form-control @ValidationClass(nameof(Address))" @bind="Address" rows="2"></textarea>
            @if (Errors.ContainsKey(nameof(Address)))
            {
                <div class="invalid-feedback d-block">@Errors[nameof(Address)]</div>
            }
        </div>

        @if (!string.IsNullOrEmpty(EmailValidationError))
        {
            <div class="alert alert-danger">@EmailValidationError</div>
        }

        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
                @if (IsValidating)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    <span>Validating…</span>
                }
                else
                {
                    <span>Next &raquo;</span>
                }
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private Dictionary<string, string> Errors { get; set; } = new();
    private string? EmailValidationError;
    private bool IsValidating;

    private string ValidationClass(string field) =>
        Errors.ContainsKey(field) ? "is-invalid" : "";

    private async Task HandleNext()
    {
        Errors.Clear();
        EmailValidationError = null;

        if (string.IsNullOrWhiteSpace(FullName)) Errors[nameof(FullName)] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email)) Errors[nameof(Email)] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone)) Errors[nameof(Phone)] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address)) Errors[nameof(Address)] = "Address is required.";

        if (Errors.Count > 0) return;

        IsValidating = true;
        try
        {
            var isValid = await ValidateEmail(Email);
            if (!isValid)
            {
                EmailValidationError = "The email address could not be validated. Please check and try again.";
                return;
            }
        }
        finally
        {
            IsValidating = false;
        }

        await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

@namespace sv_940b4722b8e342f4a1af21b574f14d25.Components.Pages.ApplyForm

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h6 class="mb-0">Position @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input class="form-control" value="@Entry.Company"
                       @onchange="e => Update(Entry with { Company = (string?)e.Value ?? "" })" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input class="form-control" value="@Entry.Title"
                       @onchange="e => Update(Entry with { Title = (string?)e.Value ?? "" })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                       @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@Entry.EndDate?.ToString("yyyy-MM-dd")"
                       disabled="@IsCurrent"
                       @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="@($"current-{Index}")" checked="@IsCurrent"
                           @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"current-{Index}")">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="2" value="@Entry.Description"
                          @onchange="e => Update(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        _ = OnChanged.InvokeAsync(updated);
    }

    private void Update(WorkEntryModel updated) => _ = OnChanged.InvokeAsync(updated);

    public record WorkEntryModel(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description)
    {
        public static WorkEntryModel Empty() => new("", "", DateTime.Today, null, false, "");
    }
}

@namespace sv_940b4722b8e342f4a1af21b574f14d25.Components.Pages.ApplyForm

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-3">Work History</h4>

        @if (!string.IsNullOrEmpty(ValidationError))
        {
            <div class="alert alert-danger">@ValidationError</div>
        }

        @for (int i = 0; i < Entries.Count; i++)
        {
            var index = i;
            <WorkEntryForm Entry="@Entries[index]"
                           Index="index"
                           CanRemove="@(Entries.Count > 1)"
                           OnChanged="e => HandleEntryChanged(index, e)"
                           OnRemove="() => RemoveEntry(index)" />
        }

        <button class="btn btn-outline-primary mb-3" @onclick="AddEntry">
            + Add Another Position
        </button>

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">&laquo; Back</button>
            <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryForm.WorkEntryModel> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryForm.WorkEntryModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    protected override void OnParametersSet()
    {
        if (Entries.Count == 0)
            Entries = new List<WorkEntryForm.WorkEntryModel> { WorkEntryForm.WorkEntryModel.Empty() };
    }

    private void HandleEntryChanged(int index, WorkEntryForm.WorkEntryModel updated)
    {
        Entries[index] = updated;
    }

    private void AddEntry() => Entries.Add(WorkEntryForm.WorkEntryModel.Empty());

    private void RemoveEntry(int index) => Entries.RemoveAt(index);

    private async Task HandleNext()
    {
        ValidationError = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ValidationError = "Each position must have a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }
}

