@namespace sv_940b4722b8e342f4a1af21b574f14d25.Components.Pages.ApplyForm

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-3">References</h4>

        @if (!string.IsNullOrEmpty(ValidationError))
        {
            <div class="alert alert-danger">@ValidationError</div>
        }

        @for (int i = 0; i < References.Count; i++)
        {
            var index = i;
            <ReferenceForm Entry="@References[index]"
                           Index="index"
                           CanRemove="@(References.Count > 2)"
                           OnChanged="e => HandleReferenceChanged(index, e)"
                           OnRemove="() => RemoveReference(index)" />
        }

        @if (References.Count < 3)
        {
            <button class="btn btn-outline-primary mb-3" @onclick="AddReference">
                + Add Reference
            </button>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">&laquo; Back</button>
            <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<ReferenceForm.ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    protected override void OnParametersSet()
    {
        if (References.Count == 0)
        {
            References = new List<ReferenceForm.ReferenceModel>
            {
                ReferenceForm.ReferenceModel.Empty(),
                ReferenceForm.ReferenceModel.Empty()
            };
        }
    }

    private void HandleReferenceChanged(int index, ReferenceForm.ReferenceModel updated)
    {
        References[index] = updated;
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(ReferenceForm.ReferenceModel.Empty());
    }

    private void RemoveReference(int index) => References.RemoveAt(index);

    private async Task HandleNext()
    {
        ValidationError = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ValidationError = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }
}

