        <div class="mb-3">
            <textarea class="form-control" rows="10" maxlength="@MaxLength"
                      @bind="CoverLetter" placeholder="Write your cover letter here..."></textarea>
            <div class="form-text text-end">
                @(CoverLetter?.Length ?? 0) / @MaxLength characters
            </div>
        </div>

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">&laquo; Back</button>
            <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
        </div>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(CoverLetter ?? "");
    }
}

@namespace sv_940b4722b8e342f4a1af21b574f14d25.Components.Pages.ApplyForm

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-3">Review & Submit</h4>

        @if (IsSubmitted)
        {
            <div class="alert alert-success text-center">
                <h5 class="alert-heading">Application Submitted!</h5>
                <p class="mb-0">Your application has been received. Your application ID is <strong>#@ApplicationId</strong>.</p>
            </div>
        }
        else
        {
            @* Personal Info *@
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
                    <h5 class="mb-0">Personal Information</h5>
                    <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
                </div>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@FullName</dd>
                    <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@Email</dd>
                    <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@Phone</dd>
                    <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@Address</dd>
                </dl>
            </div>

            @* Work History *@
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
                    <h5 class="mb-0">Work History</h5>
                    <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-2 ps-2 border-start border-3">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <small class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") &ndash;
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0 mt-1 small">@entry.Description</p>
                        }
                    </div>
                }
            </div>

            @* References *@
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
                    <h5 class="mb-0">References</h5>
                    <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
                </div>
                @foreach (var r in References)
                {
                    <div class="mb-2 ps-2 border-start border-3">
                        <strong>@r.Name</strong> — @r.Relationship<br />
                        <small class="text-muted">@r.Email · @r.Phone</small>
                    </div>
                }
            </div>

            @* Cover Letter *@
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
